/usr/bin/zsh -lc "python3 - <<'PY'
import json, pathlib, re
p=pathlib.Path('workspace/deliverable')
d=json.loads((p/'classificacoes.json').read_text())
assert set(d)=={'provisao_trabalhista','ccb_horizonte','afac','covenant'}
assert d['covenant']['cumprido'] is False
for f in p.glob('*'):
 print(f.name, f.stat().st_size)
for f in p.glob('*.md'):
 for target in re.findall(r'\\]\\((["'^)]+)'"\\)',f.read_text()):
  assert (f.parent/target).exists(),(f,target)
print('JSON and citation paths valid')
PY"

